    role = observation.get("self_role") or observation.get("role") or "pursuer"

    def step_toward(tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    if env == "pursuit_evasion":
