            return [dx, dy]
        return [1, 0]

    if env == "territory_control":
        targets = (
            as_points(observation.get("unclaimed_cells"))
            or as_points(observation.get("neutral_cells"))
            or as_points(observation.get("opponent_territory"))
            or as_points(observation.get("target_cells"))
        )
        if targets:
            best = min(targets, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
            return step_toward(best[0], best[1])
        if oxoy is not None:
            # contest the opponent when nothing else is available
            return step_toward(ox, oy)
        return [0, 0]

    resources = (
        as_points(observation.get("resources"))
        or as_points(observation.get("resource_positions"))
        or as_points(observation.get("items"))
        or as_points(observation.get("food"))
    )
    if resources:
        best = min(resources, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
        return step_toward(best[0], best[1])

    # Fallbacks for no visible resources/targets
    if oxoy is not None:
        # default contest/pressure
        dx, dy = step_toward(ox, oy)
        if dx == 0 and dy == 0:
            return [1, 0]
        return [dx, dy]
    return [1, 0]

